/* @lc app=leetcode id=946 lang=kotlin */ class Solution { fun validateStackSequences(pushed: IntArray, popped: IntArray): Boolean = java.util.ArrayDeque<Int>().let { st -> pushed.fold(0) { j, x -> st.addFirst(x).let { generateSequence(j) { it + 1 }.takeWhile { k -> k < popped.size && st.peekFirst() == popped[k] && st.pollFirst() != null }.count().let { j + it } } } == popped.size } }